// Parsear evento vindo do Asaas
const body = $input.item.json;
const event = body.event; // PAYMENT_RECEIVED, PAYMENT_OVERDUE, PAYMENT_DELETED, etc.
const payment = body.payment;

if (!payment || !event) return [{ json: { skip: true } }];

// Map Asaas status → Maestr.ia status
const statusMap = {
  PENDING: 'pendente',
  RECEIVED: 'pago',
  CONFIRMED: 'pago',
  OVERDUE: 'atrasado',
  REFUNDED: 'reembolsado',
  RECEIVED_IN_CASH: 'pago',
  REFUND_REQUESTED: 'pendente',
  CHARGEBACK_REQUESTED: 'pendente',
  CHARGEBACK_DISPUTE: 'pendente',
  AWAITING_CHARGEBACK_REVERSAL: 'pendente',
  DUNNING_REQUESTED: 'atrasado',
  DUNNING_RECEIVED: 'pago',
  AWAITING_RISK_ANALYSIS: 'pendente',
};

return [{ json: {
  event,
  asaas_id: payment.id,
  asaas_customer_id: payment.customer,
  value: payment.value,
  net_value: payment.netValue,
  due_date: payment.dueDate,
  payment_date: payment.paymentDate,
  status: statusMap[payment.status] || 'pendente',
  description: payment.description,
  billing_type: payment.billingType,
  invoice_url: payment.invoiceUrl,
  bank_slip_url: payment.bankSlipUrl,
  external_reference: payment.externalReference, // Maestr.ia payment ID
}}];

const payments = $('Buscar Pagamento no Maestr.ia').item.json;
const parsed = $('Parsear Evento Asaas').item.json;

if (!Array.isArray(payments) || payments.length === 0) {
  return [{ json: { skip: true, reason: 'payment not found: ' + parsed.external_reference } }];
}

const p = payments[0];
const updatePayload = {
  status: parsed.status,
  ...(parsed.payment_date ? { paid_at: new Date(parsed.payment_date).toISOString() } : {}),
  metadata: { asaas_id: parsed.asaas_id, invoice_url: parsed.invoice_url, bank_slip_url: parsed.bank_slip_url }
};

return [{ json: { payment_id: p.id, client_id: p.client_id, update: updatePayload, event: parsed.event } }];

// Maestr.ia → Asaas: criar cobrança quando novo pagamento pendente
const body = $input.item.json.body || $input.item.json;
const payment = body.payment;
const client = body.client;

if (!payment || !client) return [{ json: { skip: true } }];

// Map billing method
const billingMap = { boleto: 'BOLETO', pix: 'PIX', cartao: 'CREDIT_CARD', dinheiro: 'CASH' };

return [{ json: {
  customer: client.asaas_customer_id, // precisa estar cadastrado no Asaas
  billingType: billingMap[payment.payment_method] || 'BOLETO',
  value: payment.value,
  dueDate: payment.due_date,
  description: payment.description,
  externalReference: payment.id, // ID do Maestr.ia para rastrear
  postalService: false
}}];
